List<double> findClosestElements(List<double> numbers) {
  if (numbers.isEmpty) return [];

  // Sort the list first
  numbers.sort();

  double left = 0.0;
  double right = numbers.length.toDouble() - 1.0;

  while (left < right) {
    int mid = ((right - left) / 2).floor().toDouble().toInt() + left.toInt();

