List<int> evenOddPalindrome(int n) {
  List<int> digits = [];
  int temp = n;

  // Extract the digits
  while (temp > 0) {
    digits.add(temp % 10);
    temp ~/= 10;
  }

  if (digits.length == 1) return [n];

  bool isEvenLength = digits.length % 2 == 0;

  int midIndex = isEvenLength ? digits.length ~/ 2 - 1 : digits.length ~/ 2;

  List<int> leftHalf = digits.sublist(0, midIndex + 1);
  List<int> rightHalf = digits.sublist(isEvenLength ? midIndex + 1 : midIndex);

  for (int i = 0; i < leftHalf.length; ++i) {
    if (leftHalf[i] != rightHalf[rightHalf.length - 1 - i]) {
      print('No');
      return [];
    }
  }

  List<int> result = [];

  if (!isEvenLength) {
    result.addAll(leftHalf);
    result.addAll(rightHalf.reversed);
    result.removeLast();
  } else {
    result.addAll(leftHalf);
    result.addAll(rightHalf.reversed);
  }

