bool simplify(String x, String n) {
  var a = int.parse(x);
  var b = int.parse(n);

  if (a == 0 || b == 0)
    return false;

  // Check for division by zero
  if (b == 0)
    return false;

  // Ensure that the numerator and denominator are positive.
  if (a < 0 && b < 0) {
    a = abs(a);
    b = abs(b);
  } else if (a < 0 || b < 0) {
    return false;
  }

