  var gcd = _gcd(a, b);

  a ~/= gcd;
  b ~/= gcd;

  // If after simplification the denominator is not one, then it's reducible
  return b != 1;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}
